// Acceptance for the frozen public contract: same entry points, same return
// shapes, same error surface, same counters and sweep ordering, no new
// runtime dependencies, README keeps documenting the public surface.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const api = await import(pathToFileURL(path.join(root, 'src', 'index.js')).href);
const { createRegistry, LeaseTakenError, LogFileError } = api;

function clock(start = 0) {
  let now = start;
  const fn = () => now;
  fn.set = (value) => {
    now = value;
  };
  fn.advance = (delta) => {
    now += delta;
  };
  return fn;
}

function main() {
  assert.equal(typeof createRegistry, 'function', 'createRegistry must stay exported');
  assert.equal(typeof LeaseTakenError, 'function', 'LeaseTakenError must stay exported');
  assert.equal(typeof LogFileError, 'function', 'LogFileError must stay exported');
  assert.ok(LeaseTakenError.prototype instanceof Error, 'LeaseTakenError must stay an Error subclass');
  assert.ok(LogFileError.prototype instanceof Error, 'LogFileError must stay an Error subclass');

  const reg = createRegistry({ ttlMs: 100, clock: clock(0) });
  for (const name of ['acquire', 'renew', 'release', 'sweep', 'holder', 'stats', 'cancel']) {
    assert.equal(typeof reg[name], 'function', 'Registry.' + name + ' must be callable');
  }

  // acquire without a wait budget keeps the documented return structure
  const c1 = clock(1000);
  const r1 = createRegistry({ ttlMs: 100, clock: c1 });
  const lease = r1.acquire('res-a', 'alice');
  assert.deepEqual(Object.keys(lease).sort(), ['expiresAt', 'holder', 'resource', 'token']);
  assert.equal(lease.resource, 'res-a');
  assert.equal(lease.holder, 'alice');
  assert.equal(lease.expiresAt, 1100, 'expiresAt is the clock reading plus the configured ttlMs');
  assert.equal(typeof lease.token, 'string');
  assert.ok(lease.token.length > 0);

  assert.deepEqual(Object.keys(r1.stats()).sort(), ['granted', 'live', 'reclaimed', 'released', 'renewed']);
  assert.deepEqual(r1.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });
  assert.equal(r1.holder('res-a'), 'alice');
  assert.equal(r1.holder('res-b'), null);

  // invalid ttlMs values keep being rejected
  for (const bad of [0, -1, NaN, Infinity, '100']) {
    assert.throws(() => r1.acquire('res-c', 'bob', bad), TypeError);
  }

  // a taken resource without a wait budget still throws LeaseTakenError with a code
  assert.throws(
    () => r1.acquire('res-a', 'bob'),
    (error) => {
      assert.ok(error instanceof LeaseTakenError, 'contended acquire must throw LeaseTakenError');
      assert.equal(error.code, 'LEASE_TAKEN', 'LeaseTakenError keeps its code property');
      return true;
    },
  );
  assert.deepEqual(r1.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });

  // renew and release keep their boolean contract
  assert.equal(r1.renew(lease.token), true);
  assert.equal(r1.release(lease.token), true);
  assert.equal(r1.release(lease.token), false, 'a released credential is void');
  assert.equal(r1.renew(lease.token), false);
  assert.equal(r1.holder('res-a'), null);
  assert.deepEqual(r1.stats(), { granted: 1, renewed: 1, released: 1, reclaimed: 0, live: 0 });

  // live drops at the expiry instant, the reclaim counter only at the sweep
  const c2 = clock(0);
  const r2 = createRegistry({ ttlMs: 30, clock: c2 });
  const short = r2.acquire('res-x', 'carol', 30);
  c2.set(29);
  assert.deepEqual(r2.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });
  c2.set(short.expiresAt);
  assert.deepEqual(r2.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 0 });
  assert.deepEqual(r2.sweep(), ['res-x']);
  assert.deepEqual(r2.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 1, live: 0 });

  // sweep names the freed resources ordered by expiry time
  const c3 = clock(0);
  const r3 = createRegistry({ ttlMs: 100, clock: c3 });
  r3.acquire('late', 'd1', 40);
  r3.acquire('early', 'd2', 10);
  r3.acquire('mid', 'd3', 25);
  c3.set(100);
  assert.deepEqual(r3.sweep(), ['early', 'mid', 'late']);
  assert.deepEqual(r3.sweep(), [], 'a second sweep frees nothing new');

  // no runtime dependencies were introduced
  const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));

