1	// Acceptance for the wait queue behaviour from the task statement: queueing
2	// moves nothing, waiters are served strictly first come first served, a woken
3	// lease carries its own expiry, a request that runs out of wait budget gives
4	// up for good, a cancel lands exactly once and no later request jumps the line.
5	import assert from 'node:assert/strict';
6	import path from 'node:path';
7	import { fileURLToPath, pathToFileURL } from 'node:url';
8	
9	const here = path.dirname(fileURLToPath(import.meta.url));
10	const root = path.resolve(here, '..');
11	const api = await import(pathToFileURL(path.join(root, 'src', 'index.js')).href);
12	const { createRegistry, LeaseTakenError } = api;
