14	const WAITING = 'waiting';
15	const GRANTED = 'granted';
16	const GIVE_UP = new Set(['timeout', 'expired', 'timedout', 'timed-out', 'abandoned']);
17	const CANCELLED = new Set(['cancelled', 'canceled']);
18	
19	function clock(start = 0) {
20	  let now = start;
21	  const fn = () => now;
22	  fn.set = (value) => {
23	    now = value;
24	  };
25	  return fn;
26	}
27	
28	function ticketId(res) {
29	  const id = res && (res.requestId ?? res.waitId ?? res.id);
30	  assert.equal(typeof id, 'string', 'queue result must carry a request id: ' + JSON.stringify(res));
31	  assert.ok(id.length > 0, 'the request id must not be empty');
32	  return id;
33	}
34	
35	function statusOf(reg, res) {
36	  reg.stats();
37	  return res.status;
38	}
39	
40	function assertWaiting(reg, res, label) {
41	  assert.equal(statusOf(reg, res), WAITING, label + ' should still be waiting: ' + JSON.stringify(res));
42	  assert.equal(res.token, undefined, label + ' must not carry a credential while waiting');
43	}
44	
45	function assertGranted(reg, res, label) {
46	  assert.equal(statusOf(reg, res), GRANTED, label + ' should have been granted: ' + JSON.stringify(res));
47	  assert.equal(typeof res.token, 'string', label + ' must carry a credential once granted');
48	  assert.ok(res.token.length > 0, label + ' credential must not be empty');
49	  assert.equal(typeof res.expiresAt, 'number', label + ' must carry its own expiry');
50	}
51	
52	function assertGiveUp(reg, res, label) {
53	  const status = statusOf(reg, res);
54	  assert.ok(GIVE_UP.has(status), label + ' should read as given up, got ' + String(status));
55	  assert.equal(res.token, undefined, label + ' must never be handed a credential');
56	}
57	
58	function assertCancelled(reg, res, label) {
59	  const status = statusOf(reg, res);
60	  assert.ok(CANCELLED.has(status), label + ' should read as cancelled, got ' + String(status));
61	  assert.equal(res.token, undefined, label + ' must never be handed a credential');
62	}
