64	function testQueueingChangesNothing() {
65	  const c = clock(0);
66	  const reg = createRegistry({ ttlMs: 100, clock: c });
67	  reg.acquire('db-primary', 'worker-1');
68	  const w1 = reg.acquire('db-primary', 'worker-2', 40, 500);
69	  const w2 = reg.acquire('db-primary', 'worker-3', 40, 500);
70	  const id1 = ticketId(w1);
71	  const id2 = ticketId(w2);
72	  assert.notEqual(id1, id2, 'each queued request carries its own id');
73	
74	  assertWaiting(reg, w1, 'w1');
75	  assert.equal(w1.resource, 'db-primary');
76	  assert.equal(w1.holder, 'worker-2');
77	  assertWaiting(reg, w2, 'w2');
78	
79	  assert.equal(reg.holder('db-primary'), 'worker-1', 'queueing must not disturb the holder');
80	  assert.deepEqual(reg.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });
81	
82	  // without a wait budget a contended acquire still throws with a code
83	  assert.throws(
84	    () => reg.acquire('db-primary', 'worker-4'),
85	    (error) => error instanceof LeaseTakenError && typeof error.code === 'string',
86	  );
87	  // an invalid wait budget must not create an immortal waiter
88	  for (const bad of [0, -1, NaN, Infinity, 'later']) {
89	    assert.throws(() => reg.acquire('db-primary', 'worker-5', 40, bad), TypeError);
90	  }
91	  assert.deepEqual(reg.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });
92	
93	  // a free resource is granted immediately even with a wait budget
94	  const direct = reg.acquire('db-replica', 'worker-6', 40, 500);
95	  assert.equal(direct.status, undefined, 'a direct grant is not a queue result');
96	  assert.equal(typeof direct.token, 'string');
97	  assert.equal(direct.expiresAt, 40);
98	}
