100	function testFifoHandoff() {
101	  const c = clock(0);
102	  const reg = createRegistry({ ttlMs: 100, clock: c });
103	  const first = reg.acquire('db-primary', 'worker-1', 100);
104	  const w1 = reg.acquire('db-primary', 'worker-2', 40, 500);
105	  const w2 = reg.acquire('db-primary', 'worker-3', 60, 500);
106	  const w3 = reg.acquire('db-primary', 'worker-4', 70, 500);
107	
108	  c.set(10);
109	  assert.equal(reg.release(first.token), true);
110	  assertGranted(reg, w1, 'w1');
111	  assert.equal(w1.expiresAt, 50, 'the woken lease expires at handoff time plus its own ttlMs');
112	  assertWaiting(reg, w2, 'w2');
113	  assertWaiting(reg, w3, 'w3');
114	  assert.equal(reg.holder('db-primary'), 'worker-2');
115	  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });
116	
117	  c.set(20);
118	  assert.equal(reg.release(w1.token), true);
119	  assertGranted(reg, w2, 'w2');
120	  assert.equal(w2.expiresAt, 80);
121	  assertWaiting(reg, w3, 'w3');
122	
123	  assert.equal(reg.release(w2.token), true);
124	  assertGranted(reg, w3, 'w3');
125	  assert.equal(w3.expiresAt, 90);
126	  assert.deepEqual(reg.stats(), { granted: 4, renewed: 0, released: 3, reclaimed: 0, live: 1 });
127	}
128	
129	function testReclaimHandsToQueueInExpiryOrder() {
130	  const c = clock(0);
131	  const reg = createRegistry({ ttlMs: 100, clock: c });
132	  reg.acquire('x', 'worker-1', 10);
133	  reg.acquire('y', 'worker-2', 20);
134	  const wx = reg.acquire('x', 'worker-3', 50, 1000);
135	  const wy = reg.acquire('y', 'worker-4', 60, 1000);
136	
137	  c.set(25);
138	  assert.deepEqual(reg.sweep(), ['x', 'y'], 'sweep still reports freed resources in expiry order');
139	  assertGranted(reg, wx, 'wx');
140	  assert.equal(wx.expiresAt, 75);
141	  assertGranted(reg, wy, 'wy');
142	  assert.equal(wy.expiresAt, 85);
143	  assert.equal(reg.holder('x'), 'worker-3');
144	  assert.equal(reg.holder('y'), 'worker-4');
145	  assert.deepEqual(reg.stats(), { granted: 4, renewed: 0, released: 0, reclaimed: 2, live: 2 });
146	}
147	
148	function testTimeoutGivesUpAndIsNeverWoken() {
149	  const c = clock(0);
150	  const reg = createRegistry({ ttlMs: 100, clock: c });
151	  const lease = reg.acquire('slot-7', 'alpha', 100);
152	  const w1 = reg.acquire('slot-7', 'beta', 40, 20);
153	  const w2 = reg.acquire('slot-7', 'gamma', 40, 1000);
154	  const id1 = ticketId(w1);
155	
156	  c.set(15);
157	  assertWaiting(reg, w1, 'w1');
158	  assertWaiting(reg, w2, 'w2');
159	
160	  c.set(50);
161	  assert.equal(reg.release(lease.token), true);
162	  assertGiveUp(reg, w1, 'w1');
163	  assert.equal(reg.cancel(id1), false, 'a request that gave up cannot be cancelled any more');
164	  assertGranted(reg, w2, 'w2');
165	  assert.equal(w2.expiresAt, 90);
166	  assert.equal(reg.holder('slot-7'), 'gamma');
167	  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });
168	
169	  // a request that gave up is never handed the lease later either
170	  assert.equal(reg.release(w2.token), true);
171	  assertGiveUp(reg, w1, 'w1');
172	  assert.equal(reg.holder('slot-7'), null);
173	  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 2, reclaimed: 0, live: 0 });
174	}
175	
176	function testCancelLandsExactlyOnce() {
177	  const c = clock(0);
178	  const reg = createRegistry({ ttlMs: 100, clock: c });
179	  const lease = reg.acquire('slot-9', 'alpha', 100);
180	  const w1 = reg.acquire('slot-9', 'beta', 40, 500);
181	  const w2 = reg.acquire('slot-9', 'gamma', 40, 500);
182	  const id1 = ticketId(w1);
183	  const id2 = ticketId(w2);
184	
185	  assert.equal(reg.cancel(id1), true, 'the first cancel lands');
186	  assertCancelled(reg, w1, 'w1');
187	  assert.equal(reg.cancel(id1), false, 'a repeat cancel shows that nothing landed');
188	  assert.equal(reg.cancel('request-does-not-exist'), false, 'an unknown request is not landed');
189	
190	  assert.equal(reg.release(lease.token), true);
191	  assertCancelled(reg, w1, 'w1');
192	  assertGranted(reg, w2, 'w2');
193	  assert.equal(reg.holder('slot-9'), 'gamma');
194	  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });
195	
196	  // an already woken request can no longer be cancelled
197	  assert.equal(reg.cancel(id2), false, 'an already woken request cannot be cancelled');
198	  assert.equal(reg.holder('slot-9'), 'gamma');
199	}
200	
201	function testLateAcquireCannotJumpTheQueue() {
202	  const c = clock(0);
203	  const reg = createRegistry({ ttlMs: 100, clock: c });
204	  reg.acquire('slot-3', 'alpha', 10);
205	  const w1 = reg.acquire('slot-3', 'beta', 40, 1000);
206	  const w2 = reg.acquire('slot-3', 'gamma', 40, 1000);
207	
208	  c.set(20);
209	  assert.throws(
210	    () => reg.acquire('slot-3', 'delta'),
211	    (error) => error instanceof LeaseTakenError,
212	    'a late acquisition must not take a resource an earlier request is waiting for',
213	  );
214	
215	  // a late waiting acquire only joins the back of the line
216	  const w3 = reg.acquire('slot-3', 'delta', 40, 1000);
217	  assertWaiting(reg, w3, 'w3');
218	
219	  reg.sweep();
220	  assertGranted(reg, w1, 'w1');
221	  assertWaiting(reg, w2, 'w2');
222	  assertWaiting(reg, w3, 'w3');
223	  assert.equal(reg.holder('slot-3'), 'beta');
224	
225	  assert.equal(reg.release(w1.token), true);
226	  assertGranted(reg, w2, 'w2');
227	  assertWaiting(reg, w3, 'w3');
228	  assert.equal(reg.holder('slot-3'), 'gamma');
229	}
230	
231	function testRenewDuringWaitKeepsOrder() {
232	  const c = clock(0);
233	  const reg = createRegistry({ ttlMs: 100, clock: c });
234	  const lease = reg.acquire('slot-4', 'alpha', 40);
235	  const w = reg.acquire('slot-4', 'beta', 30, 1000);
236	
237	  c.set(30);
238	  assert.equal(reg.renew(lease.token), true, 'the old credential can still be renewed');
239	  assertWaiting(reg, w, 'w');
240	  assert.equal(reg.holder('slot-4'), 'alpha');
241	
242	  c.set(50);
243	  assertWaiting(reg, w, 'w');
244	  assert.equal(reg.holder('slot-4'), 'alpha');
245	
246	  c.set(80);
247	  assert.deepEqual(reg.sweep(), ['slot-4']);
248	  assertGranted(reg, w, 'w');
249	  assert.equal(w.expiresAt, 110, 'the woken lease carries its own expiry from the handoff moment');
250	}
251	
252	function testWokenLeaseLifetimeAndCounters() {
253	  const c = clock(0);
254	  const reg = createRegistry({ ttlMs: 100, clock: c });
255	  reg.acquire('slot-5', 'alpha', 10);
256	  const w = reg.acquire('slot-5', 'beta', 30, 1000);
257	
258	  c.set(15);
259	  assert.deepEqual(reg.sweep(), ['slot-5']);
260	  assertGranted(reg, w, 'w');
261	  assert.equal(w.expiresAt, 45);
262	  c.set(44);
263	  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 1, live: 1 });
264	  c.set(45);
265	  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 1, live: 0 }, 'live drops at the expiry instant');
266	  assert.deepEqual(reg.sweep(), ['slot-5']);
267	  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 2, live: 0 }, 'reclaim only counts at the sweep');
268	}
269	
270	function testClockGoingBackwardsIsTakenAsGiven() {
271	  const c = clock(100);
272	  const reg = createRegistry({ ttlMs: 50, clock: c });
273	  const lease = reg.acquire('slot-6', 'alpha');
274	  const w = reg.acquire('slot-6', 'beta', 30, 1000);
275	
276	  c.set(10);
277	  assert.equal(reg.holder('slot-6'), 'alpha', 'the lease is read against the injected clock');
278	  assert.equal(reg.renew(lease.token), true);
279	  assertWaiting(reg, w, 'w');
280	  assert.deepEqual(reg.stats(), { granted: 1, renewed: 1, released: 0, reclaimed: 0, live: 1 });
281	}
282	
283	try {
284	  testQueueingChangesNothing();
285	  testFifoHandoff();
286	  testReclaimHandsToQueueInExpiryOrder();
287	  testTimeoutGivesUpAndIsNeverWoken();
288	  testCancelLandsExactlyOnce();
289	  testLateAcquireCannotJumpTheQueue();
290	  testRenewDuringWaitKeepsOrder();
291	  testWokenLeaseLifetimeAndCounters();
292	  testClockGoingBackwardsIsTakenAsGiven();
293	  console.log('queue-behavior: ok');
294	} catch (error) {
295	  console.error(error && error.stack ? error.stack : error);
296	  process.exit(1);
297	}
