// Acceptance for the wait queue behaviour from the task statement: queueing
// moves nothing, waiters are served strictly first come first served, a woken
// lease carries its own expiry, a request that runs out of wait budget gives
// up for good, a cancel lands exactly once and no later request jumps the line.
import assert from 'node:assert/strict';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const api = await import(pathToFileURL(path.join(root, 'src', 'index.js')).href);
const { createRegistry, LeaseTakenError } = api;

const WAITING = 'waiting';
const GRANTED = 'granted';
const GIVE_UP = new Set(['timeout', 'expired', 'timedout', 'timed-out', 'abandoned']);
const CANCELLED = new Set(['cancelled', 'canceled']);

function clock(start = 0) {
  let now = start;
  const fn = () => now;
  fn.set = (value) => {
    now = value;
  };
  return fn;
}

function ticketId(res) {
  const id = res && (res.requestId ?? res.waitId ?? res.id);
  assert.equal(typeof id, 'string', 'queue result must carry a request id: ' + JSON.stringify(res));
  assert.ok(id.length > 0, 'the request id must not be empty');
  return id;
}

function statusOf(reg, res) {
  reg.stats();
  return res.status;
}

function assertWaiting(reg, res, label) {
  assert.equal(statusOf(reg, res), WAITING, label + ' should still be waiting: ' + JSON.stringify(res));
  assert.equal(res.token, undefined, label + ' must not carry a credential while waiting');
}

function assertGranted(reg, res, label) {
  assert.equal(statusOf(reg, res), GRANTED, label + ' should have been granted: ' + JSON.stringify(res));
  assert.equal(typeof res.token, 'string', label + ' must carry a credential once granted');
  assert.ok(res.token.length > 0, label + ' credential must not be empty');
  assert.equal(typeof res.expiresAt, 'number', label + ' must carry its own expiry');
}

function assertGiveUp(reg, res, label) {
  const status = statusOf(reg, res);
  assert.ok(GIVE_UP.has(status), label + ' should read as given up, got ' + String(status));
  assert.equal(res.token, undefined, label + ' must never be handed a credential');
}

function assertCancelled(reg, res, label) {
  const status = statusOf(reg, res);
  assert.ok(CANCELLED.has(status), label + ' should read as cancelled, got ' + String(status));
  assert.equal(res.token, undefined, label + ' must never be handed a credential');
}

function testQueueingChangesNothing() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  reg.acquire('db-primary', 'worker-1');
  const w1 = reg.acquire('db-primary', 'worker-2', 40, 500);
  const w2 = reg.acquire('db-primary', 'worker-3', 40, 500);
  const id1 = ticketId(w1);
  const id2 = ticketId(w2);
  assert.notEqual(id1, id2, 'each queued request carries its own id');

  assertWaiting(reg, w1, 'w1');
  assert.equal(w1.resource, 'db-primary');
  assert.equal(w1.holder, 'worker-2');
  assertWaiting(reg, w2, 'w2');

  assert.equal(reg.holder('db-primary'), 'worker-1', 'queueing must not disturb the holder');
  assert.deepEqual(reg.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });

  // without a wait budget a contended acquire still throws with a code
  assert.throws(
    () => reg.acquire('db-primary', 'worker-4'),
    (error) => error instanceof LeaseTakenError && typeof error.code === 'string',
  );
  // an invalid wait budget must not create an immortal waiter
  for (const bad of [0, -1, NaN, Infinity, 'later']) {
    assert.throws(() => reg.acquire('db-primary', 'worker-5', 40, bad), TypeError);
  }
  assert.deepEqual(reg.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });

  // a free resource is granted immediately even with a wait budget
  const direct = reg.acquire('db-replica', 'worker-6', 40, 500);
  assert.equal(direct.status, undefined, 'a direct grant is not a queue result');
  assert.equal(typeof direct.token, 'string');
  assert.equal(direct.expiresAt, 40);
}

function testFifoHandoff() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  const first = reg.acquire('db-primary', 'worker-1', 100);
  const w1 = reg.acquire('db-primary', 'worker-2', 40, 500);
  const w2 = reg.acquire('db-primary', 'worker-3', 60, 500);
  const w3 = reg.acquire('db-primary', 'worker-4', 70, 500);

  c.set(10);
  assert.equal(reg.release(first.token), true);
  assertGranted(reg, w1, 'w1');
  assert.equal(w1.expiresAt, 50, 'the woken lease expires at handoff time plus its own ttlMs');
  assertWaiting(reg, w2, 'w2');
  assertWaiting(reg, w3, 'w3');
  assert.equal(reg.holder('db-primary'), 'worker-2');
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });

  c.set(20);
  assert.equal(reg.release(w1.token), true);
  assertGranted(reg, w2, 'w2');
  assert.equal(w2.expiresAt, 80);
  assertWaiting(reg, w3, 'w3');

  assert.equal(reg.release(w2.token), true);
  assertGranted(reg, w3, 'w3');
  assert.equal(w3.expiresAt, 90);
  assert.deepEqual(reg.stats(), { granted: 4, renewed: 0, released: 3, reclaimed: 0, live: 1 });
}

function testReclaimHandsToQueueInExpiryOrder() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  reg.acquire('x', 'worker-1', 10);
  reg.acquire('y', 'worker-2', 20);
  const wx = reg.acquire('x', 'worker-3', 50, 1000);
  const wy = reg.acquire('y', 'worker-4', 60, 1000);

  c.set(25);
  assert.deepEqual(reg.sweep(), ['x', 'y'], 'sweep still reports freed resources in expiry order');
  assertGranted(reg, wx, 'wx');
  assert.equal(wx.expiresAt, 75);
  assertGranted(reg, wy, 'wy');
  assert.equal(wy.expiresAt, 85);
  assert.equal(reg.holder('x'), 'worker-3');
  assert.equal(reg.holder('y'), 'worker-4');
  assert.deepEqual(reg.stats(), { granted: 4, renewed: 0, released: 0, reclaimed: 2, live: 2 });
}

function testTimeoutGivesUpAndIsNeverWoken() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  const lease = reg.acquire('slot-7', 'alpha', 100);
  const w1 = reg.acquire('slot-7', 'beta', 40, 20);
  const w2 = reg.acquire('slot-7', 'gamma', 40, 1000);
  const id1 = ticketId(w1);

  c.set(15);
  assertWaiting(reg, w1, 'w1');
  assertWaiting(reg, w2, 'w2');

  c.set(50);
  assert.equal(reg.release(lease.token), true);
  assertGiveUp(reg, w1, 'w1');
  assert.equal(reg.cancel(id1), false, 'a request that gave up cannot be cancelled any more');
  assertGranted(reg, w2, 'w2');
  assert.equal(w2.expiresAt, 90);
  assert.equal(reg.holder('slot-7'), 'gamma');
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });

  // a request that gave up is never handed the lease later either
  assert.equal(reg.release(w2.token), true);
  assertGiveUp(reg, w1, 'w1');
  assert.equal(reg.holder('slot-7'), null);
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 2, reclaimed: 0, live: 0 });
}

function testCancelLandsExactlyOnce() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  const lease = reg.acquire('slot-9', 'alpha', 100);
  const w1 = reg.acquire('slot-9', 'beta', 40, 500);
  const w2 = reg.acquire('slot-9', 'gamma', 40, 500);
  const id1 = ticketId(w1);
  const id2 = ticketId(w2);

  assert.equal(reg.cancel(id1), true, 'the first cancel lands');
  assertCancelled(reg, w1, 'w1');
  assert.equal(reg.cancel(id1), false, 'a repeat cancel shows that nothing landed');
  assert.equal(reg.cancel('request-does-not-exist'), false, 'an unknown request is not landed');

  assert.equal(reg.release(lease.token), true);
  assertCancelled(reg, w1, 'w1');
  assertGranted(reg, w2, 'w2');
  assert.equal(reg.holder('slot-9'), 'gamma');
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });

  // an already woken request can no longer be cancelled
  assert.equal(reg.cancel(id2), false, 'an already woken request cannot be cancelled');
  assert.equal(reg.holder('slot-9'), 'gamma');
}

function testLateAcquireCannotJumpTheQueue() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  reg.acquire('slot-3', 'alpha', 10);
  const w1 = reg.acquire('slot-3', 'beta', 40, 1000);
  const w2 = reg.acquire('slot-3', 'gamma', 40, 1000);

  c.set(20);
  assert.throws(
    () => reg.acquire('slot-3', 'delta'),
    (error) => error instanceof LeaseTakenError,
    'a late acquisition must not take a resource an earlier request is waiting for',
  );

  // a late waiting acquire only joins the back of the line
  const w3 = reg.acquire('slot-3', 'delta', 40, 1000);
  assertWaiting(reg, w3, 'w3');

  reg.sweep();
  assertGranted(reg, w1, 'w1');
  assertWaiting(reg, w2, 'w2');
  assertWaiting(reg, w3, 'w3');
  assert.equal(reg.holder('slot-3'), 'beta');

  assert.equal(reg.release(w1.token), true);
  assertGranted(reg, w2, 'w2');
  assertWaiting(reg, w3, 'w3');
  assert.equal(reg.holder('slot-3'), 'gamma');
}

function testRenewDuringWaitKeepsOrder() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  const lease = reg.acquire('slot-4', 'alpha', 40);
  const w = reg.acquire('slot-4', 'beta', 30, 1000);

  c.set(30);
  assert.equal(reg.renew(lease.token), true, 'the old credential can still be renewed');
  assertWaiting(reg, w, 'w');
  assert.equal(reg.holder('slot-4'), 'alpha');

  c.set(50);
  assertWaiting(reg, w, 'w');
  assert.equal(reg.holder('slot-4'), 'alpha');

  c.set(80);
  assert.deepEqual(reg.sweep(), ['slot-4']);
  assertGranted(reg, w, 'w');
  assert.equal(w.expiresAt, 110, 'the woken lease carries its own expiry from the handoff moment');
}

function testWokenLeaseLifetimeAndCounters() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  reg.acquire('slot-5', 'alpha', 10);
  const w = reg.acquire('slot-5', 'beta', 30, 1000);

  c.set(15);
  assert.deepEqual(reg.sweep(), ['slot-5']);
  assertGranted(reg, w, 'w');
  assert.equal(w.expiresAt, 45);
  c.set(44);
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 1, live: 1 });
  c.set(45);
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 1, live: 0 }, 'live drops at the expiry instant');
  assert.deepEqual(reg.sweep(), ['slot-5']);
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 2, live: 0 }, 'reclaim only counts at the sweep');
}

function testClockGoingBackwardsIsTakenAsGiven() {
  const c = clock(100);
  const reg = createRegistry({ ttlMs: 50, clock: c });
  const lease = reg.acquire('slot-6', 'alpha');
  const w = reg.acquire('slot-6', 'beta', 30, 1000);

  c.set(10);
  assert.equal(reg.holder('slot-6'), 'alpha', 'the lease is read against the injected clock');
  assert.equal(reg.renew(lease.token), true);
  assertWaiting(reg, w, 'w');
  assert.deepEqual(reg.stats(), { granted: 1, renewed: 1, released: 0, reclaimed: 0, live: 1 });
}

try {
  testQueueingChangesNothing();
  testFifoHandoff();
  testReclaimHandsToQueueInExpiryOrder();
  testTimeoutGivesUpAndIsNeverWoken();
  testCancelLandsExactlyOnce();
  testLateAcquireCannotJumpTheQueue();
  testRenewDuringWaitKeepsOrder();
  testWokenLeaseLifetimeAndCounters();
  testClockGoingBackwardsIsTakenAsGiven();
  console.log('queue-behavior: ok');
} catch (error) {
  console.error(error && error.stack ? error.stack : error);
  process.exit(1);
}

