// Acceptance for the interaction between the wait queue and the append-only
// log: queueing writes nothing, a handoff is persisted and replays as an
// ordinary grant, queued requests do not survive a restart, and a failed
// append rolls the whole operation back without touching the line.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const api = await import(pathToFileURL(path.join(root, 'src', 'index.js')).href);
const { createRegistry, LeaseTakenError, LogFileError } = api;

const WAITING = 'waiting';
const GRANTED = 'granted';

function clock(start = 0) {
  let now = start;
  const fn = () => now;
  fn.set = (value) => {
    now = value;
  };
  return fn;
}

function ticketId(res) {
  const id = res && (res.requestId ?? res.waitId ?? res.id);
  assert.equal(typeof id, 'string', 'queue result must carry a request id: ' + JSON.stringify(res));
  return id;
}

function statusOf(reg, res) {
  reg.stats();
  return res.status;
}

function assertWaiting(reg, res, label) {
  assert.equal(statusOf(reg, res), WAITING, label + ' should still be waiting: ' + JSON.stringify(res));
  assert.equal(res.token, undefined, label + ' must not carry a credential while waiting');
}

function assertGranted(reg, res, label) {
  assert.equal(statusOf(reg, res), GRANTED, label + ' should have been granted: ' + JSON.stringify(res));
  assert.equal(typeof res.token, 'string', label + ' must carry a credential once granted');
  assert.equal(typeof res.expiresAt, 'number', label + ' must carry its own expiry');
}

function readTypes(file) {
  return fs.readFileSync(file, 'utf8')
    .split(/\r?\n/)
    .filter((line) => line.trim().length > 0)
    .map((line) => JSON.parse(line).type);
}

function readLineCount(file) {
  return fs.readFileSync(file, 'utf8').split(/\r?\n/).filter((line) => line.trim().length > 0).length;
}

function sabotage(file) {
  fs.renameSync(file, file + '.bak');
  fs.mkdirSync(file);
}

function restore(file) {
  fs.rmdirSync(file);
  fs.renameSync(file + '.bak', file);
}

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-queue-acceptance-'));

function testQueueingWritesNothing() {
  const file = path.join(dir, 'queueing.log');
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c, logPath: file });
  const first = reg.acquire('r', 'a');
  assert.deepEqual(readTypes(file), ['acquire']);
  const w1 = reg.acquire('r', 'b', 40, 500);
  const w2 = reg.acquire('r', 'c', 40, 500);
  ticketId(w1);
  ticketId(w2);
  assert.deepEqual(readTypes(file), ['acquire'], 'queueing must not append log events');
  assert.deepEqual(reg.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });

  c.set(10);
  assert.equal(reg.release(first.token), true);
  assertGranted(reg, w1, 'w1');
  assert.equal(w1.expiresAt, 50);
  assertWaiting(reg, w2, 'w2');
  assert.deepEqual(readTypes(file), ['acquire', 'release', 'acquire']);
}

function testHandoffIsLoggedAndReplays() {
  const file = path.join(dir, 'replay.log');
  const c = clock(0);
  let reg = createRegistry({ ttlMs: 100, clock: c, logPath: file });
  const first = reg.acquire('r', 'a');
  const w = reg.acquire('r', 'b', 40, 500);
  c.set(10);
  assert.equal(reg.release(first.token), true);
  assertGranted(reg, w, 'w');

  reg = createRegistry({ ttlMs: 100, clock: clock(10), logPath: file });
  assert.equal(reg.holder('r'), 'b', 'the woken lease replays like any other grant');
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });
  assert.equal(reg.renew(w.token), false, 'credentials issued before the restart are void');
  assert.equal(reg.release(w.token), false);
  assert.deepEqual(reg.sweep(49), []);
  assert.deepEqual(reg.sweep(50), ['r'], 'the woken lease keeps its own expiry');
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 1, live: 0 });
}

function testQueuedRequestDoesNotSurviveRestart() {
  const file = path.join(dir, 'restart.log');
  let reg = createRegistry({ ttlMs: 100, clock: clock(0), logPath: file });
  reg.acquire('r', 'a');
  const w = reg.acquire('r', 'b', 40, 500);
  const id = ticketId(w);
  reg = createRegistry({ ttlMs: 100, clock: clock(0), logPath: file });
  assert.equal(reg.cancel(id), false, 'queued requests live in memory only');
  assert.throws(() => reg.acquire('r', 'c'), (error) => error instanceof LeaseTakenError);
  assert.deepEqual(reg.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });
}

function testFailedAppendOnWakingReleaseRollsBack() {
  const file = path.join(dir, 'rollback-release.log');
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c, logPath: file });
  const first = reg.acquire('r', 'a');
  const w = reg.acquire('r', 'b', 40, 500);

  sabotage(file);
  try {
    assert.throws(
      () => reg.release(first.token),
      (error) => error instanceof LogFileError && error.code === 'LOG_FILE_ERROR',
    );
  } finally {
    restore(file);
  }

  assert.equal(reg.holder('r'), 'a', 'a failed log write leaves the holder untouched');
  assertWaiting(reg, w, 'w');
  assert.deepEqual(reg.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });
  assert.equal(readLineCount(file), 1, 'a rolled back operation leaves no log line');

  assert.equal(reg.release(first.token), true);
  assertGranted(reg, w, 'w');
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });
}

function testFailedAppendOnWakingSweepRollsBack() {
  const file = path.join(dir, 'rollback-sweep.log');
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c, logPath: file });
  reg.acquire('r', 'a', 10);
  const w = reg.acquire('r', 'b', 40, 500);
  c.set(20);

  sabotage(file);
  try {
    assert.throws(() => reg.sweep(), (error) => error instanceof LogFileError);
  } finally {
    restore(file);
  }

  assertWaiting(reg, w, 'w');
  assert.deepEqual(reg.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 0 });

  assert.deepEqual(reg.sweep(), ['r']);
  assertGranted(reg, w, 'w');
  assert.equal(w.expiresAt, 60);
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 1, live: 1 });
}

function testWithoutWaitersNothingExtraHappens() {
  const file = path.join(dir, 'no-waiters.log');
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c, logPath: file });
  const first = reg.acquire('r1', 'a', 30);
  assert.equal(reg.release(first.token), true);
  reg.acquire('r2', 'b', 10);
  c.set(25);
  assert.deepEqual(reg.sweep(), ['r2']);
  assert.deepEqual(reg.sweep(), []);
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 1, live: 0 });
  assert.deepEqual(readTypes(file), ['acquire', 'release', 'acquire', 'reclaim']);
}

function testLogFileProblems() {
  const missing = path.join(dir, 'missing.log');
  const empty = createRegistry({ ttlMs: 100, clock: clock(0), logPath: missing });
  assert.deepEqual(empty.stats(), { granted: 0, renewed: 0, released: 0, reclaimed: 0, live: 0 });

  const corrupt = path.join(dir, 'corrupt.log');
  fs.writeFileSync(corrupt, 'this is not a json line\n');
  assert.throws(
    () => createRegistry({ ttlMs: 100, clock: clock(0), logPath: corrupt }),
    (error) => error instanceof LogFileError && error.code === 'LOG_FILE_ERROR',
  );

  const badVersion = path.join(dir, 'bad-version.log');
  fs.writeFileSync(
    badVersion,
    JSON.stringify({ v: 999, type: 'acquire', at: 0, token: 't1', resource: 'r', holder: 'h', ttlMs: 10, expiresAt: 10 }) + '\n',
  );
  assert.throws(
    () => createRegistry({ ttlMs: 100, clock: clock(0), logPath: badVersion }),
    (error) => error instanceof LogFileError,
  );
}

try {
  testQueueingWritesNothing();
  testHandoffIsLoggedAndReplays();
  testQueuedRequestDoesNotSurviveRestart();
  testFailedAppendOnWakingReleaseRollsBack();
  testFailedAppendOnWakingSweepRollsBack();
  testWithoutWaitersNothingExtraHappens();
  testLogFileProblems();
  console.log('queue-persistence: ok');
} catch (error) {
  console.error(error && error.stack ? error.stack : error);
  process.exit(1);
}

