  });
  for (const lease of group.leases) {
    assert.equal(registry.release(lease.token), false);
  }
  assert.deepEqual(registry.sweep(49), []);
  assert.deepEqual(registry.sweep(50), ['a']);
  assert.deepEqual(registry.sweep(70), ['b']);
});

