  assert.equal(g.status, 'granted');
  assert.equal(g.leases.length, 2);
  assert.equal(s2.status, 'waiting');
  assert.equal(r.holder('x'), 'G');
  assert.equal(r.stats().live, 2);
  assert.throws(() => r.acquire('x', 'late'), (e) => e instanceof LeaseTakenError);
  // releasing just one twin keeps s2 waiting (one live credential remains)
  r.release(g.leases[0].token);
  assert.equal(s2.status, 'waiting');
  assert.equal(r.holder('x'), 'G');
  r.release(g.leases[1].token);
  assert.equal(s2.status, 'granted');
  assert.equal(r.holder('x'), 'S2');
}

// 20. Waiting group ticket exposes requestId alias and cancel works through it
{
  const r = createRegistry({ ttlMs: 100, clock: clock(0) });
  r.acquire('a', 'A');
  const g = r.acquireAll(['a', 'b'], 'G', 10, 1000);
  assert.equal(g.requestId, g.waitId);
  assert.equal(r.cancel(g.requestId), true);
  assert.equal(g.status, 'cancelled');
}

// 21. Cascade wake in ONE release: two groups chained on distinct resources in same event is
// impossible without shared resources, but a release waking g whose other positions were all
// already free, and g's grant itself cannot wake h in the same release unless h only needs
// resources freed by this release too — verified via sweep of many expiries, arrival order.
{
  const c = clock(0);
  const r = createRegistry({ ttlMs: 100, clock: c });
  r.acquire('a', 'A', 5);
  r.acquire('b', 'B', 5);
  r.acquire('c', 'C', 5);
  // chain: G wants a,b; H wants b,c — b contended, so only G wakes this sweep
  const g = r.acquireAll(['a', 'b'], 'G', 10, 1000);
  const h = r.acquireAll(['b', 'c'], 'H', 10, 1000);
  c.set(10);
  r.sweep();
  assert.equal(g.status, 'granted');
  assert.equal(h.status, 'waiting');
  assert.equal(r.stats().granted, 5); // 3 holders + 2 grants
}

// 22. Persisted single acquire keeps baseline event shape (no batch field requirement)
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
{
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-shape-'));
  const p = path.join(dir, 'x.log');
  const r = createRegistry({ ttlMs: 100, clock: clock(0), logPath: p });
  r.acquire('r', 'h', 10);
  const ev = JSON.parse(fs.readFileSync(p, 'utf8').trim());
  assert.deepEqual(Object.keys(ev).sort(), ['at', 'batch', 'expiresAt', 'holder', 'resource', 'token', 'ttlMs', 'type', 'v']);
  fs.rmSync(dir, { recursive: true, force: true });
}

// 23. Old-format log (baseline acquire without batch) still replays
{
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-old-'));
  const p = path.join(dir, 'x.log');
  fs.writeFileSync(p, JSON.stringify({ v: 1, type: 'acquire', at: 0, token: 'old-1', resource: 'r', holder: 'h', ttlMs: 100, expiresAt: 100 }) + '\n');
  const r = createRegistry({ ttlMs: 100, clock: clock(0), logPath: p });
  assert.equal(r.holder('r'), 'h');
  assert.equal(r.renew('old-1'), false);
  fs.rmSync(dir, { recursive: true, force: true });
}

